result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_cache_and_stats.py", "content": "import pytest

from app import create_app
from cache import cached


class FakeClock:
    """Injectable monotonic-ish clock; advance virtual time, never sleep."""

    def __init__(self, start=0.0):
        self.now = start

    def __call__(self):
        return self.now

    def advance(self, seconds):
        self.now += seconds


@pytest.fixture()
def fake_clock():
    return FakeClock()


@pytest.fixture()
def client(fake_clock):
    app = create_app(db_path=":memory:", clock=fake_clock)
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


def compute_calls(client):
    return client.application.extensions["compute_calls"]["count"]


# ---------- decorator unit tests ----------

def test_decorator_caches_within_ttl(fake_clock):
    calls = []

    @cached(ttl_seconds=10, clock=fake_clock)
    def f(x):
        calls.append(x)
        return x * 2

    assert f(1) == 2
    fake_clock.advance(9.999)
    assert f(1) == 2
    assert calls == [1]
    info = f.cache_info()
    assert (info["hits"], info["misses"]) == (1, 1)


def test_decorator_expires_after_ttl(fake_clock):
    calls = []

    @cached(ttl_seconds=10, clock=fake_clock)
    def f():
        calls.append(1)
        return len(calls)

    assert f() == 1
    fake_clock.advance(10)  # exactly at expiry -> stale
    assert f() == 2
    assert f.cache_info()["expiries"] == 1


def test_decorator_explicit_invalidation(fake_clock):
    calls = []

    @cached(ttl_seconds=60, clock=fake_clock)
    def f():
        calls.append(1)
        return len(calls)

    assert f() == 1
    fake_clock.advance(5)
    f.cache_invalidate()
    assert f() == 2  # recomputed despite being well inside TTL


# ---------- endpoint integration tests ----------

def test_two_hits_within_ttl_compute_once(client, fake_clock):
    r1 = client.get("/stats")
    assert r1.status_code == 200
    body1 = r1.get_json()

    fake_clock.advance(29)  # inside the 30s TTL
    r2 = client.get("/stats")

    assert r2.get_json() == body1
    assert compute_calls(client) == 1


def test_recomputes_after_expiry(client, fake_clock):
    client.get("/stats")
    fake_clock.advance(31)  # past the 30s TTL
    client.get("/stats")
    assert compute_calls(client) == 2


def test_post_orders_invalidates_cache_within_ttl(client, fake_clock):
    before = client.get("/stats").get_json()
    assert compute_calls(client) == 1

    fake_clock.advance(3)  # still inside TTL
    resp = client.post(
        "/orders", json={"customer": "frank", "amount": 500.0}
    )
    assert resp.status_code == 201

    after = client.get("/stats").get_json()  # must recompute
    assert compute_calls(client) == 2
    assert after["orders"] == before["orders"] + 1
    assert after["total_amount"] == round(before["total_amount"] + 500.0, 2)


def test_stats_shape_on_seed_data(client):
    body = client.get("/stats").get_json()
    assert body["orders"] == 5
    assert body["total_amount"] == round(120.0 + 75.5 + 210.25 + 40.0 + 95.75, 2)


def test_post_order_validation(client):
    assert client.post("/orders", json={"amount": 10}).status_code == 400
    assert client.post("/orders", json={"customer": "x"}).status_code == 400
